struct DropAddZero;
impl Fold for DropAddZero {
    fn fold_expr(&mut self, expr: Expr) -> Expr {
        let expr = fold_expr(self, expr);            // trait default walks children
        match expr {                                 // shape plus action
            Expr::Binary(b) if is_add(&b) && is_zero(&b.right) => *b.left,  // x + 0 -> x
            other => other,
        }
    }
}
